<?php
declare(strict_types=1);require __DIR__.'/app/bootstrap.php';require_once __DIR__.'/app/doctor_online_v580.php';if(!do580_enabled()){http_response_code(404);exit('Doctor Online module unavailable.');}$orgs=do580_organizations(true);$type=(string)($_GET['type']??'');if($type)$orgs=array_values(array_filter($orgs,fn($o)=>$o['org_type']===$type));do580_track('facilities_view');do580_public_header('Hospitals & Clinics','Browse local hospitals, clinics and e-clinics connected with Doctor Online.');?>
<section class="do580-pagehead"><div class="do580-shell"><h1>Hospitals, clinics & e-clinics</h1><p>Browse verified local healthcare facilities, doctor networks, contact details and map locations.</p></div></section><main class="do580-shell" style="padding:28px 0 56px"><form class="do580-filter" style="grid-template-columns:1fr auto"><select name="type"><option value="">All facilities</option><option value="hospital" <?=$type==='hospital'?'selected':''?>>Hospitals</option><option value="clinic" <?=$type==='clinic'?'selected':''?>>Clinics</option><option value="eclinic" <?=$type==='eclinic'?'selected':''?>>E-Clinics</option><option value="diagnostic" <?=$type==='diagnostic'?'selected':''?>>Diagnostics</option></select><button class="do580-btn primary">Filter</button></form><div class="do580-org-grid"><?php foreach($orgs as $o):$fac=do580_decode($o['facilities_json']);?><article class="do580-org-card"><div class="org-icon"><?=e($o['org_type']==='hospital'?'H':'✚')?></div><div class="do580-badges"><?php if($o['verified']):?><span class="do580-badge verified">VERIFIED</span><?php endif;?><?php if($o['emergency_available']):?><span class="do580-badge" style="background:#fff0f1;color:#c21f2d">EMERGENCY</span><?php endif;?></div><h3><?=e($o['name'])?></h3><p><?=e(ucwords(str_replace('_',' ',$o['org_type'])))?> · <?=e($o['area']?:$o['address']?:'Local facility')?></p><p>☎ <?=e($o['phone']?:'Contact via portal')?><?php if($o['emergency_phone']):?> · Emergency <?=e($o['emergency_phone'])?><?php endif;?></p><?php if($fac):?><p><?=e(implode(' · ',array_slice($fac,0,5)))?></p><?php endif;?><div style="display:flex;gap:8px;flex-wrap:wrap"><a class="do580-btn secondary" href="/find-doctor.php?org_id=<?=(int)$o['id']?>">View Doctors</a><?php if($o['map_url']):?><a class="do580-btn white" target="_blank" rel="noopener" href="<?=e($o['map_url'])?>">Map ↗</a><?php endif;?></div></article><?php endforeach;?><?php if(!$orgs):?><div class="do580-panel">No healthcare facilities are published yet.</div><?php endif;?></div></main><?php do580_public_footer(); ?>
